#!/bin/bash
# Claude Code status line — Dracula theme + token tracking
# Generated by webup-statusline skill, enhanced with token stats

# Colors
readonly RST='\033[0m'
readonly BOLD='\033[1m'
readonly DIM='\033[2m'
readonly C_MODEL='\033[38;2;189;147;249m'
readonly C_CTX_OK='\033[38;2;80;250;123m'
readonly C_CTX_WARN='\033[38;2;241;250;140m'
readonly C_CTX_LOW='\033[38;2;255;85;85m'
readonly C_BAR_EMPTY='\033[38;2;68;71;90m'
readonly C_PCT='\033[38;2;248;248;242m'
readonly C_DIR='\033[38;2;139;233;253m'
readonly C_GIT='\033[38;2;255;184;108m'
readonly C_GIT_DIRTY='\033[38;2;241;250;140m'
readonly C_VIM='\033[38;2;241;250;140m'
readonly C_WORKTREE='\033[38;2;255;121;198m'
readonly C_STYLE='\033[38;2;189;147;249m'
readonly C_COST='\033[38;2;255;215;0m'
readonly C_EFFORT_HIGH='\033[1;38;2;255;85;85m'
readonly C_EFFORT_MED='\033[38;2;241;250;140m'
readonly C_EFFORT_LOW='\033[38;2;80;250;123m'
readonly C_EFFORT_OFF='\033[2;38;2;98;114;164m'
readonly C_SEP='\033[38;2;98;114;164m'
readonly C_TOKEN='\033[38;2;248;248;242m'
readonly C_TOKEN_LABEL='\033[38;2;98;114;164m'

readonly SEP=" | "

# Read JSON from stdin
input=$(cat)

model=$(echo "$input" | jq -r '.model.display_name // ""')
ctx_size=$(echo "$input" | jq -r '.context_window.context_window_size // empty')
remaining=$(echo "$input" | jq -r '.context_window.remaining_percentage // ""')
used_pct_from_json=$(echo "$input" | jq -r '.context_window.used_percentage // empty')
transcript_path=$(echo "$input" | jq -r '.transcript_path // ""')
current_dir=$(echo "$input" | jq -r '.workspace.current_dir // ""')
original_repo_dir=$(echo "$input" | jq -r '.worktree.original_repo_dir // empty')
output_style=$(echo "$input" | jq -r '.output_style.name // empty')
cost_usd=$(echo "$input" | jq -r '.cost.total_cost_usd // empty')
duration_ms=$(echo "$input" | jq -r '.cost.total_duration_ms // empty')
lines_added=$(echo "$input" | jq -r '.cost.total_lines_added // empty')
lines_removed=$(echo "$input" | jq -r '.cost.total_lines_removed // empty')
worktree_name=$(echo "$input" | jq -r '.worktree.name // empty')
worktree_branch=$(echo "$input" | jq -r '.worktree.branch // empty')

# Current usage from stdin (most accurate for context window)
cur_input=$(echo "$input" | jq -r '.context_window.current_usage.input_tokens // 0')
cur_cache_read=$(echo "$input" | jq -r '.context_window.current_usage.cache_read_input_tokens // 0')
cur_cache_create=$(echo "$input" | jq -r '.context_window.current_usage.cache_creation_input_tokens // 0')

# Effort: prefer env CLAUDE_CODE_EFFORT_LEVEL, fallback to effortLevel in settings
effort=""
# Check env first
for f in "$HOME/.claude/settings.local.json" "$HOME/.claude/settings.json"; do
  if [ -z "$effort" ] && [ -f "$f" ]; then
    effort=$(jq -r '.env.CLAUDE_CODE_EFFORT_LEVEL // empty' "$f" 2>/dev/null)
  fi
done
# Fallback to root-level effortLevel
if [ -z "$effort" ]; then
  for f in "$HOME/.claude/settings.local.json" "$HOME/.claude/settings.json"; do
    if [ -z "$effort" ] && [ -f "$f" ]; then
      effort=$(jq -r '.effortLevel // empty' "$f" 2>/dev/null)
    fi
  done
fi

# ── Token tracking via Python helper ──────────────
SCRIPT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
# Detect Python: try known paths, then PATH
PYTHON=""
for p in /d/work/miniconda/python /c/Users/yuhua/miniconda3/python.exe /c/Users/yuhua/AppData/Local/Programs/Python/Python3*/python.exe; do
  if [ -x "$p" ] 2>/dev/null; then PYTHON="$p"; break; fi
done
if [ -z "$PYTHON" ]; then
  for p in python3 python; do
    if command -v "$p" > /dev/null 2>&1; then
      # Verify it actually works (Windows App Execution Aliases return exit 49)
      if "$p" -c "pass" > /dev/null 2>&1; then PYTHON="$p"; break; fi
    fi
  done
fi
token_json=""
if [ -n "$PYTHON" ]; then
  token_json=$("$PYTHON" "$SCRIPT_DIR/token_helper.py" "$transcript_path" "$ctx_size" "$cur_input" "$cur_cache_read" "$cur_cache_create" 2>/dev/null)
fi

token_in="0"
token_out="0"
token_cache_cr="0"
token_cache_rd="0"
token_total="0"
ctx_used_val="0"
ctx_size_val=""
ctx_pct_val=""

if [ -n "$token_json" ]; then
  token_in=$(echo "$token_json" | jq -r '.in // "0"')
  token_out=$(echo "$token_json" | jq -r '.out // "0"')
  token_cache_cr=$(echo "$token_json" | jq -r '.cache_cr // "0"')
  token_cache_rd=$(echo "$token_json" | jq -r '.cache_rd // "0"')
  token_total=$(echo "$token_json" | jq -r '.total // "0"')
  ctx_used_val=$(echo "$token_json" | jq -r '.ctx_used // "0"')
  ctx_size_val=$(echo "$token_json" | jq -r '.ctx_size // empty')
  ctx_pct_val=$(echo "$token_json" | jq -r '.ctx_pct // empty')
fi

# Fallback: if no token data, use JSON values for context
if [ -z "$ctx_size_val" ] && [ -n "$ctx_size" ]; then
  # Format ctx_size
  if [ "$ctx_size" -ge 1000000 ]; then
    ctx_size_val=$(awk -v v="$ctx_size" 'BEGIN { printf "%.1fM", v/1000000 }')
  elif [ "$ctx_size" -ge 1000 ]; then
    ctx_size_val=$(awk -v v="$ctx_size" 'BEGIN { printf "%.1fK", v/1000 }')
  else
    ctx_size_val="$ctx_size"
  fi
fi

# ── Worktree detection ────────────────────────────
is_worktree=0
if [ -n "$worktree_name" ]; then
  is_worktree=1
elif [ -n "$current_dir" ] && git -C "$current_dir" --no-optional-locks rev-parse --git-dir > /dev/null 2>&1; then
  _gd=$(git -C "$current_dir" --no-optional-locks rev-parse --git-dir 2>/dev/null)
  _gcd=$(git -C "$current_dir" --no-optional-locks rev-parse --git-common-dir 2>/dev/null)
  if [ -n "$_gd" ] && [ -n "$_gcd" ] && [ "$_gd" != "$_gcd" ]; then
    is_worktree=1
    if [ -z "$worktree_name" ]; then
      _parent=$(dirname "$current_dir")
      worktree_name=$(basename "$_parent")
      case "$worktree_name" in
        worktrees|wt|.codex|.claude) worktree_name=$(basename "$current_dir") ;;
      esac
    fi
  fi
fi

# ── Git branch ────────────────────────────────────
git_branch="$worktree_branch"
git_dirty=0
if [ -n "$current_dir" ] && git -C "$current_dir" --no-optional-locks rev-parse --git-dir > /dev/null 2>&1; then
  if [ -z "$git_branch" ]; then
    git_branch=$(git -C "$current_dir" --no-optional-locks branch --show-current 2>/dev/null)
  fi
  if [ -n "$git_branch" ]; then
    if ! git -C "$current_dir" --no-optional-locks diff --quiet 2>/dev/null || \
       ! git -C "$current_dir" --no-optional-locks diff --cached --quiet 2>/dev/null; then
      git_dirty=1
    fi
  fi
fi

# ── Shorten directory ─────────────────────────────
short_dir=""
if [ -n "$original_repo_dir" ]; then
  short_dir=$(basename "$original_repo_dir")
elif [ -n "$current_dir" ]; then
  short_dir=$(basename "$current_dir")
fi

# ── Context progress bar ──────────────────────────
bar=""
# Prefer JSONL-derived percentage, fallback to JSON
bar_pct=""
if [ -n "$ctx_pct_val" ]; then
  bar_pct="$ctx_pct_val"
elif [ -n "$used_pct_from_json" ]; then
  bar_pct="$used_pct_from_json"
elif [ -n "$remaining" ]; then
  bar_pct=$((100 - remaining))
fi

if [ -n "$bar_pct" ]; then
  filled=$((bar_pct / 5))
  empty=$((20 - filled))
  if [ "$bar_pct" -ge 80 ]; then
    ctx_color="$C_CTX_LOW"
  elif [ "$bar_pct" -ge 50 ]; then
    ctx_color="$C_CTX_WARN"
  else
    ctx_color="$C_CTX_OK"
  fi

  # Build value string: used/total (pct%)
  ctx_val="${ctx_used_val}/${ctx_size_val} (${bar_pct}%)"

  bar="${C_SEP}[${RST}"
  for ((i=0; i<filled; i++)); do bar+="${ctx_color}■${RST}"; done
  for ((i=0; i<empty; i++)); do bar+="${C_BAR_EMPTY}□${RST}"; done
  bar+="${C_SEP}]${RST} ${ctx_color}${ctx_val}${RST}"
fi

# ── Duration formatter ────────────────────────────
fmt_duration() {
  local ms=$1
  if [ "$ms" -le 0 ]; then echo "0s"; return; fi
  local s=$((ms / 1000))
  local m=$((s / 60)); s=$((s % 60))
  local h=$((m / 60)); m=$((m % 60))
  if [ "$h" -gt 0 ]; then echo "${h}h${m}m"
  elif [ "$m" -gt 0 ]; then echo "${m}m${s}s"
  else echo "${s}s"
  fi
}

# ── Assemble single-line output ────────────────────
parts=()

if [ -n "$model" ]; then
  parts+=("${C_MODEL}◈ ${model}${RST}")
fi

if [ -n "$bar" ]; then
  parts+=("${bar}")
fi

if [ -n "$token_json" ]; then
  parts+=("${C_TOKEN_LABEL}In:${RST}${C_TOKEN}${token_in}${RST} ${C_TOKEN_LABEL}Out:${RST}${C_TOKEN}${token_out}${RST} ${C_TOKEN_LABEL}Cache:${RST}${C_TOKEN}+${token_cache_cr}/${token_cache_rd}${RST} ${C_TOKEN_LABEL}Total:${RST}${C_TOKEN}${token_total}${RST}")
fi

if [ -n "$cost_usd" ]; then
  cost_formatted=$(awk -v v="$cost_usd" 'BEGIN { if (v+0 >= 0.005) printf "$%.2f", v+0 }')
  if [ -n "$cost_formatted" ]; then
    parts+=("${C_COST}${cost_formatted}${RST}")
  fi
fi

if [ -n "$duration_ms" ] && [ "$duration_ms" != "0" ] && [ "$duration_ms" != "null" ]; then
  dur=$(fmt_duration "$duration_ms")
  parts+=("${C_TOKEN_LABEL}⏱${RST} ${C_TOKEN}${dur}${RST}")
fi

if { [ -n "$lines_added" ] && [ "$lines_added" != "0" ] && [ "$lines_added" != "null" ]; } || \
   { [ -n "$lines_removed" ] && [ "$lines_removed" != "0" ] && [ "$lines_removed" != "null" ]; }; then
  la=${lines_added:-0}; lr=${lines_removed:-0}
  parts+=("${C_CTX_OK}+${la}${RST} ${C_CTX_LOW}-${lr}${RST}")
fi

if [ -n "$effort" ]; then
  case "$effort" in
    max|MAX|Max|xhigh|XHIGH|XHigh|high|High|HIGH)  effort_color="$C_EFFORT_HIGH" ;;
    medium|Medium|MEDIUM)                          effort_color="$C_EFFORT_MED" ;;
    low|Low|LOW|xlow|XLow|XLOW|minimal|Minimal)    effort_color="$C_EFFORT_LOW" ;;
    *)                                             effort_color="$C_EFFORT_OFF" ;;
  esac
  parts+=("${effort_color}↯ ${effort}${RST}")
fi

if [ -n "$output_style" ] && [ "$output_style" != "default" ]; then
  parts+=("${C_STYLE}❋ ${output_style}${RST}")
fi

if [ -n "$short_dir" ]; then
  parts+=("${C_DIR}⌂ ${short_dir}${RST}")
fi

if [ "$is_worktree" -eq 1 ] && [ -n "$worktree_name" ]; then
  parts+=("\033[1m${C_WORKTREE}⊕ worktree:${worktree_name}${RST}")
fi

if [ -n "$git_branch" ]; then
  if [ "$git_dirty" -eq 1 ]; then
    parts+=("${C_GIT_DIRTY}⎇ ${git_branch}${RST}")
  else
    parts+=("${C_GIT}⎇ ${git_branch}${RST}")
  fi
fi

# Output single line
output=""
for i in "${!parts[@]}"; do
  if [ "$i" -gt 0 ]; then
    output+="${C_SEP}${SEP}${RST}"
  fi
  output+="${parts[$i]}"
done

printf "%b" "$output"
